// SPEC-DATA-REQUIREMENTS — the retrieve AGGREGATION, against the synthetic ExampleReadingControl 1.0.0
// (`__fixtures__/spec-patterns/ExampleReadingControl.cql`).
//
// THE FIXTURE IS A REFERENCE SET, not ELM (SPEC-EXPLAIN-INPUTS). What is exercised here is the
// inversion into per-read-with-call-sites, the reachability filter and the `mustSupport` join —
// the parts that are this file's responsibility.
//
// IT IS GENERATED BY THE REAL EXTRACTOR (`cql_databricks_designer/explain/reference_set.py`) from the ELM
// committed beside it (`scripts/build-ui-fixtures.sh`), and a Python test asserts it still matches what the
// extractor produces. Hand-writing it would have re-created the second implementation this change removed, one
// tree over.

import { describe, it, expect } from "vitest";
import { boundTerminology, buildRetrieves, readsForDefine, referencedTerminology,
  terminologyForDefine } from "./specRetrieves.ts";
import type { SpecModel } from "./specModel.ts";
import refsets from "./__fixtures__/spec-patterns-refset.json";
import type { ReferenceSet, RefSetRead, SpecRetrieve } from "./specRetrieves.ts";

const refset = refsets.root;
const REFSETS = [refset as unknown as ReferenceSet];

const LIB = "ExampleReadingControl";

/** A model containing exactly these defines — standing in for what `filterSpecModel` hands over.
 *
 *  Visibility is the MODEL's answer: the derivation reads what it is given and never re-tests
 *  `eliminated`. That contract is the subject of its own case below, because breaking it made "Show
 *  eliminated" a no-op for terminology while every other test still passed. */
function modelWith(defines: string[]): SpecModel {
  return {
    populations: [],
    libraries: [{
      name: LIB, isRoot: true, resolved: true, domId: "lib",
      entries: defines.map((name) => ({
        key: `${LIB}::${name}`, name, kind: "define" as const, library: LIB,
        variants: [], eliminated: false, domId: `d-${name}`,
      })),
    }],
    graph: { nodes: [], byId: {} },
  } as unknown as SpecModel;
}

const ALL = refset.defines.map((d) => d.name);

describe("buildRetrieves (SPEC-DATA-REQUIREMENTS)", () => {
  it("dedupes to one row per (type, filter) pair, not per resource type", () => {
    const rows = buildRetrieves(modelWith(ALL), REFSETS, new Map());
    const conditions = rows.filter((r) => r.type === "Condition");
    // Three value sets — three reads, each issued against two QICore profiles. The PROFILE is derived
    // and kept, but it does not split the row: a key that splits on a value the reader cannot see
    // produces rows that look identical and are not.
    expect(conditions).toHaveLength(3);
    expect(conditions.every((r) => r.profiles.length === 2)).toBe(true);
    expect(new Set(conditions.flatMap((r) => r.profiles))).toEqual(new Set([
      "qicore-condition-problems-health-concerns",
      "qicore-condition-encounter-diagnosis",
    ]));
  });

  it("names the value set as Terminology declares it, never as an OID", () => {
    const rows = buildRetrieves(modelWith(ALL), REFSETS, new Map());
    const names = rows.map((r) => r.valueSet).filter(Boolean);
    expect(names).toContain("Example Condition Diagnoses");
    expect(names).toContain("Example Unreached Conditions");
    expect(names.some((n) => n!.includes("2.16.840"))).toBe(false);
  });

  it("anchors each read to a line in its OWN define's body, so the citation lands", () => {
    const rows = buildRetrieves(modelWith(ALL), REFSETS, new Map());
    const diagnoses = rows.find((r) => r.valueSet === "Example Condition Diagnoses");
    // Both profile reads sit on lines 1 and 2 of the define's own body.
    expect(diagnoses?.usedBy).toEqual([
      { define: "Example Condition Diagnosis", library: LIB, span: "1" },
      { define: "Example Condition Diagnosis", library: LIB, span: "2" },
    ]);
  });

  it("ELIMINATION EXTENDS TO READS — a define nothing reaches contributes none", () => {
    // The blocker this derivation exists to solve: unioning `Library.dataRequirement` over a measure's
    // closure yields rows for every helper the closure carries, because the resource cannot say which
    // define asked. Deriving per define makes reachability the SAME rule the document already
    // runs on rather than a second opinion about what matters.
    const all = buildRetrieves(modelWith(ALL), REFSETS, new Map());
    const narrowed = buildRetrieves(
      modelWith(["Example Condition Diagnosis"]), REFSETS, new Map());
    expect(narrowed.length).toBeLessThan(all.length);
    expect(narrowed.every((r) => r.usedBy.every((s) => s.define === "Example Condition Diagnosis")))
      .toBe(true);
  });

  it("carries mustSupport across from the published resource, joined on the triple", () => {
    const requirements = new Map([[LIB, [{
      type: "Condition",
      profile: ["http://hl7.org/fhir/us/qicore/StructureDefinition/qicore-condition-encounter-diagnosis"],
      mustSupport: ["code"],
      codeFilter: [{ path: "code", valueSet: "http://example.org/fhir/ValueSet/Example Unreached Conditions" }],
    }]]]);
    const rows = buildRetrieves(modelWith(ALL), REFSETS, requirements);
    const unreached = rows.find((r) => r.valueSet === "Example Unreached Conditions");
    expect(unreached?.mustSupport).toEqual(["code"]);
  });

  it("an unfiltered read is still a read", () => {
    const rows = buildRetrieves(modelWith(ALL), REFSETS, new Map());
    const readings = rows.filter((r) => r.type === "Observation");
    expect(readings.length).toBeGreaterThan(0);
    expect(readings.every((r) => r.profiles.includes("qicore-simple-observation"))).toBe(true);
  });
});

describe("referencedTerminology (SPEC-DERIVED-APPENDIX)", () => {
  it("lists EVERYTHING the visible logic names — filters included, nothing subtracted", () => {
    // Terminology is the registry, not the leftovers. A value set legitimately appears both here
    // (with its OID, stated once) and under the read it filters; the two answer different questions.
    const named = referencedTerminology(modelWith(ALL), REFSETS);
    expect(named.valueSets.has(`${LIB}::Example Condition Diagnoses`)).toBe(true);
    expect(named.valueSets.has(`${LIB}::Example Unreached Conditions`)).toBe(true);
    // And terminology the logic only COMPARES against, which filters no read at all.
    expect(named.codes.has(`${LIB}::Example Reading A`)).toBe(true);
    expect(named.codes.has(`${LIB}::Example Reading B`)).toBe(true);
  });

  it("ELIMINATION EXTENDS TO TERMINOLOGY — a value set only unreachable logic names is not listed", () => {
    const narrowed = referencedTerminology(
      modelWith(["Example Condition Diagnosis"]), REFSETS);
    expect(narrowed.valueSets.has(`${LIB}::Example Condition Diagnoses`)).toBe(true);
    // Example Unreached Conditions is named only by `Unreached Condition`, which is not reachable here.
    expect(narrowed.valueSets.has(`${LIB}::Example Unreached Conditions`)).toBe(false);
  });
});

describe("visibility is the model's answer, not the derivation's (APP-SPEC-MODEL)", () => {
  /** A model that still CONTAINS an eliminated entry — what `filterSpecModel(model, true)` returns
   *  when the reader turns "Show eliminated" on. The derivation must honour it. */
  function modelIncludingEliminated(): SpecModel {
    return {
      populations: [],
      libraries: [{
        name: LIB, isRoot: true, resolved: true, domId: "lib",
        entries: ALL.map((name) => ({
          key: `${LIB}::${name}`, name, kind: "define" as const, library: LIB,
          variants: [], eliminated: true, domId: `d-${name}`,
        })),
      }],
      graph: { nodes: [], byId: {} },
    } as unknown as SpecModel;
  }

  it("SHOW ELIMINATED reveals reads the default view hides", () => {
    const shown = buildRetrieves(modelIncludingEliminated(), REFSETS, new Map());
    expect(shown.length).toBeGreaterThan(0);
  });

  it("SHOW ELIMINATED reveals terminology the default view hides", () => {
    // The bug this pins: the derivation re-tested `eliminated` on entries the model had already
    // decided to include, so turning the toggle on stripped exactly what it was asked to reveal.
    const named = referencedTerminology(modelIncludingEliminated(), REFSETS);
    expect(named.valueSets.has(`${LIB}::Example Unreached Conditions`)).toBe(true);
  });
});

// The Terminology tab leads with what the selection BINDS, structurally, and layers hit counts on top.
// These pin the derivation that makes that possible — and specifically that it does not consult a run,
// because "bound but never exercised" has to survive as a finding rather than render as absence.
describe("boundTerminology / readsForDefine (SPEC-DERIVED-APPENDIX)", () => {
  const read = (over: Partial<SpecRetrieve>): SpecRetrieve => ({
    key: "k", type: "Condition", profiles: [], valueSet: null, code: null, codeProperty: null,
    mustSupport: [], usedBy: [], ...over,
  });

  it("takes only the reads the named define issues, matched on LIBRARY AND NAME", () => {
    // Two libraries declaring one define name is routine (`SPEC-ANCHOR`), so a name-only match would
    // pull another library's reads into this selection's terminology.
    const mine = read({ key: "a", valueSet: "Example Condition Diagnoses",
      usedBy: [{ define: "Has Example Condition", library: LIB, span: null }] });
    const theirs = read({ key: "b", valueSet: "Someone Else's",
      usedBy: [{ define: "Has Example Condition", library: "OtherLib", span: null }] });

    const got = readsForDefine([mine, theirs], "Has Example Condition", LIB);
    expect(got).toEqual([mine]);
    expect(boundTerminology(got).valueSets).toEqual(["Example Condition Diagnoses"]);
  });

  it("dedupes a value set bound by several reads, keeping document order", () => {
    const bound = boundTerminology([
      read({ valueSet: "Example Office Visit" }),
      read({ valueSet: "Example Condition Diagnoses" }),
      read({ valueSet: "Example Office Visit" }),
    ]);
    expect(bound.valueSets).toEqual(["Example Office Visit", "Example Condition Diagnoses"]);
  });

  it("keeps direct reference codes APART from value sets", () => {
    // A code filter and a value-set filter are different bindings, and the tab renders them as
    // different blocks — collapsing them would report a code as membership in a set.
    const bound = boundTerminology([read({ code: "Birth date" }), read({ valueSet: "Example Office Visit" })]);
    expect(bound.codes).toEqual(["Birth date"]);
    expect(bound.valueSets).toEqual(["Example Office Visit"]);
  });

  it("reports a binding with no reads as empty, never as absent input", () => {
    expect(boundTerminology([])).toEqual({ valueSets: [], codes: [] });
  });
});

// THE PUSH-DOWN GAP. Terminology reaches a RETRIEVE only where the translator pushed the filter into it.
// A define that retrieves broadly and narrows in a `where` references terminology no retrieve mentions,
// and a retrieve-derived list drops it silently — which is why the Terminology tab reads the define's
// own reference list instead. Pinned against an extractor-built reference set, not a hand-built case.
describe("terminologyForDefine covers what a retrieve filter does not (SPEC-EXPLAIN-INPUTS)", () => {
  const READING_A = "Lowest Reading A On Most Recent Day";

  it("finds a code referenced in a where clause, which no retrieve carries", () => {
    const def = refset.defines.find((d) => d.name === READING_A);
    expect(def, `${READING_A} is missing from the fixture`).toBeDefined();

    // The premise: this define's reads carry NO code filter at all.
    const reads = (def!.reads ?? []) as RefSetRead[];
    const fromReads = boundTerminology(reads.map((r) => ({
      key: "k", type: r.resourceType, profiles: [], valueSet: r.valueSet ?? null,
      code: r.code ?? null, codeProperty: r.codeProperty ?? null, mustSupport: [], usedBy: [],
    })));
    expect(fromReads.codes).toEqual([]);

    // The define nonetheless references one, and the reference set is where it lives.
    const got = terminologyForDefine(REFSETS, READING_A, LIB);
    expect(got.codes).toContain("Example Reading A");
  });

  it("still reports terminology that IS a retrieve filter", () => {
    // The broader source must not lose the ordinary case it replaces.
    const got = terminologyForDefine(REFSETS, "Example Condition Diagnosis", LIB);
    expect(got.valueSets).toContain("Example Condition Diagnoses");
  });

  it("is library-qualified — a same-named define elsewhere is not this define", () => {
    expect(terminologyForDefine(REFSETS, READING_A, "SomeOtherLibrary"))
      .toEqual({ valueSets: [], codes: [] });
  });
});
